PRAGMA foreign_keys=ON;
CREATE TABLE IF NOT EXISTS users(id INTEGER PRIMARY KEY, name TEXT NOT NULL, email TEXT UNIQUE NOT NULL, password_hash TEXT NOT NULL, role TEXT NOT NULL CHECK(role IN ('admin','staff','customer')));
CREATE TABLE IF NOT EXISTS products(id INTEGER PRIMARY KEY, name TEXT NOT NULL, product_type TEXT NOT NULL, sales_price REAL NOT NULL CHECK(sales_price>=0), cost_price REAL NOT NULL CHECK(cost_price>=0), notes TEXT DEFAULT '');
CREATE TABLE IF NOT EXISTS product_variants(id INTEGER PRIMARY KEY, product_id INTEGER NOT NULL REFERENCES products(id), variant_name TEXT NOT NULL, variant_value TEXT NOT NULL, price_adjustment REAL NOT NULL DEFAULT 0);
CREATE TABLE IF NOT EXISTS plans(id INTEGER PRIMARY KEY, name TEXT NOT NULL, price REAL NOT NULL CHECK(price>=0), billing_interval TEXT NOT NULL CHECK(billing_interval IN ('daily','weekly','monthly','yearly')), min_quantity INTEGER NOT NULL DEFAULT 1, available_from TEXT, available_until TEXT, auto_close INTEGER NOT NULL DEFAULT 0);
CREATE TABLE IF NOT EXISTS subscriptions(id INTEGER PRIMARY KEY, subscription_number TEXT UNIQUE NOT NULL, customer_id INTEGER NOT NULL REFERENCES users(id), plan_id INTEGER NOT NULL REFERENCES plans(id), start_date TEXT NOT NULL, expiry_date TEXT, status TEXT NOT NULL CHECK(status IN ('Draft','Quotation','Confirmed','Active','Paused','Closed')));
CREATE TABLE IF NOT EXISTS subscription_lines(id INTEGER PRIMARY KEY, subscription_id INTEGER NOT NULL REFERENCES subscriptions(id), product_id INTEGER NOT NULL REFERENCES products(id), quantity INTEGER NOT NULL CHECK(quantity>=1), unit_price REAL NOT NULL CHECK(unit_price>=0), tax_rate REAL NOT NULL DEFAULT 0);
CREATE TABLE IF NOT EXISTS invoices(id INTEGER PRIMARY KEY, invoice_number TEXT UNIQUE NOT NULL, subscription_id INTEGER NOT NULL REFERENCES subscriptions(id), invoice_date TEXT NOT NULL, due_date TEXT, subtotal REAL NOT NULL, tax REAL NOT NULL DEFAULT 0, discount REAL NOT NULL DEFAULT 0, total REAL NOT NULL, status TEXT NOT NULL CHECK(status IN ('Draft','Confirmed','Paid','Cancelled')));
CREATE TABLE IF NOT EXISTS payments(id INTEGER PRIMARY KEY, invoice_id INTEGER NOT NULL REFERENCES invoices(id), method TEXT NOT NULL, amount REAL NOT NULL CHECK(amount>0), payment_date TEXT NOT NULL, note TEXT DEFAULT '');
